result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/test_spatialhash.py", "content": "import random
import time

import pytest

from spatialhash import SpatialHash, brute_force_pairs, narrow_phase


def make_circles(n=1000, side=500, seed=7):
    rng = random.Random(seed)
    return [
        (i, rng.uniform(0, side), rng.uniform(0, side), rng.uniform(1, 3))
        for i in range(n)
    ]


def run_hash(circles, cell_size=6.0):
    sh = SpatialHash(cell_size)
    for c in circles:
        sh.insert(c)
    return set(sh.candidate_pairs())


@pytest.fixture(scope="module")
def circles():
    return make_circles()


def test_candidate_superset_and_exact_match(circles):
    truth = brute_force_pairs(circles)
    candidates = run_hash(circles)
    assert truth <= candidates, "spatial hash missed true collisions"
    hits = narrow_phase(circles, candidates)
    assert hits == truth


def test_hash_is_faster_than_brute_force(circles):
    repeats = 20

    t0 = time.perf_counter()
    for _ in range(repeats):
        brute_force_pairs(circles)
    t_brute = time.perf_counter() - t0

    t0 = time.perf_counter()
    for _ in range(repeats):
        run_hash(circles)
    t_hash_total = time.perf_counter() - t0

    print(f"\nbrute force : {t_brute / repeats:.4f} s per repeat "
          f"(total {t_brute:.4f} s)")
    print(f"spatial hash: {t_hash_total / repeats:.4f} s per repeat "
          f"(total {t_hash_total:.4f} s)")
    print(f"speedup     : {t_brute / t_hash_total:.2f}x")

    assert t_brute >= 3 * t_hash_total
